mapper.select:
SELECT
    count(*)
FROM
    BASIL_SEC_PRD.PREP_MASTER_ORDER pmo
    JOIN BASIL_ODS_PRD.MASTER_CUSTOMER mc USING(MC_OID)
    LEFT JOIN BASIL_SEC_PRD.XREF_RESPONSE resp USING(MO_OID)
    LEFT JOIN BASIL_SEC_PRD.USERS user ON resp.RESPONSE_BY = user.U_OID
    LEFT JOIN BASIL_SEC_PRD.SUPPORT_CLIENT_ATTRIBUTE_VALUES scavdept ON pmo.ORDER_DEPT = scavdept.SCV_OID
    LEFT JOIN BASIL_SEC_PRD.SUPPORT_CLIENT_ATTRIBUTE_VALUES scavtype ON pmo.ORDER_TYPE = scavtype.SCV_OID


        AND mc.MC_OID = #{id}


        AND pmo.MO_OID = #{ticketId}


        AND scavdept.VALUE = #{department}


        AND scavtype.VALUE = #{type}


        AND user.NAME = #{responder} OR user.NAME IS NULL


        AND pmo.ORDER_DATE BETWEEN #{createdFromDate} AND #{createdToDate}

SELECT pmo.MO_OID as ticketId, pmo.ORDER_STATUS as status, scavdept.VALUE as department, scavtype.VALUE as type, mc.CUSTOMER_ORGANIZATION as customerOrganization, pmo.ORDER_DATE as createdDate, user.NAME as responder FROM BASIL_SEC_PRD.PREP_MASTER_ORDER pmo JOIN BASIL_ODS_PRD.MASTER_CUSTOMER mc USING(MC_OID) LEFT JOIN BASIL_SEC_PRD.XREF_RESPONSE resp USING(MO_OID) LEFT JOIN BASIL_SEC_PRD.USERS user ON resp.RESPONSE_BY = user.U_OID LEFT JOIN BASIL_SEC_PRD.SUPPORT_CLIENT_ATTRIBUTE_VALUES scavdept ON pmo.ORDER_DEPT = scavdept.SCV_OID LEFT JOIN BASIL_SEC_PRD.SUPPORT_CLIENT_ATTRIBUTE_VALUES scavtype ON pmo.ORDER_TYPE = scavtype.SCV_OID
pmo.ACKNOWLEDGED = 0
AND mc.MC_OID = #{id}
AND pmo.MO_OID = #{ticketId}
AND scavdept.VALUE = #{department}
AND scavtype.VALUE = #{type}
AND user.NAME = #{responder} OR user.NAME IS NULL
AND pmo.ORDER_DATE BETWEEN #{createdFromDate} AND #{createdToDate}
ORDER BY ${sortColumns}
LIMIT #{offset,jdbcType=INTEGER},#{count,jdbcType=INTEGER}
